from __future__ import annotations

import argparse
import base64
import gzip
import re
import sys
from email import policy
from email.message import Message
from email.parser import BytesParser
from pathlib import Path

ADDRESS_MARKER = "Houston, TX 77018"

# Hardcoded signature content that should appear after ADDRESS_MARKER.
# Stored compressed so this script is self-contained but still practical to copy.
SIGNATURE_HTML_AFTER_ADDRESS_GZ_B64 = """

""".strip()

SIGNATURE_TEXT_AFTER_ADDRESS_GZ_B64 = "H4sIAMqBEGoC/+MqLy/XSyxKzkhMLcpMzNFLzs/lAgCXErOdFAAAAA=="


def _decode_signature(blob: str) -> str:
    return gzip.decompress(base64.b64decode(blob)).decode("utf-8")


SIGNATURE_HTML_AFTER_ADDRESS = _decode_signature(SIGNATURE_HTML_AFTER_ADDRESS_GZ_B64)
SIGNATURE_TEXT_AFTER_ADDRESS = _decode_signature(SIGNATURE_TEXT_AFTER_ADDRESS_GZ_B64)


def _parse_message(path: Path) -> Message:
    with path.open("rb") as handle:
        return BytesParser(policy=policy.default).parse(handle)


def _first_part(message: Message, content_type: str) -> Message | None:
    if message.get_content_type() == content_type:
        return message
    for part in message.walk():
        if part.get_content_type() == content_type:
            return part
    return None


def _split_html_after_address(html: str) -> str:
    marker = re.search(re.escape(ADDRESS_MARKER), html, flags=re.IGNORECASE)
    if not marker:
        raise ValueError(f'Could not find "{ADDRESS_MARKER}" in HTML content.')

    paragraph_end = re.search(r"</p\s*>", html[marker.end():], flags=re.IGNORECASE)
    if paragraph_end:
        split_at = marker.end() + paragraph_end.end()
    else:
        split_at = marker.end()
    return html[:split_at]


def _split_text_after_address(text: str) -> str:
    marker = re.search(re.escape(ADDRESS_MARKER), text, flags=re.IGNORECASE)
    if not marker:
        raise ValueError(f'Could not find "{ADDRESS_MARKER}" in plain text content.')
    return text[:marker.end()]


def _set_text_part_content(part: Message, content: str, subtype: str) -> None:
    charset = part.get_content_charset() or "utf-8"
    cte = (part.get("Content-Transfer-Encoding") or "").lower()
    valid_ctes = {"7bit", "8bit", "quoted-printable", "base64"}
    kwargs = {"subtype": subtype, "charset": charset}
    if cte in valid_ctes:
        kwargs["cte"] = cte
    part.set_content(content, **kwargs)


def format_eml_in_place(target_path: Path) -> None:
    if not target_path.exists():
        raise FileNotFoundError(f"Target file does not exist: {target_path}")
    if target_path.suffix.lower() != ".eml":
        raise ValueError(f"Target is not an .eml file: {target_path}")

    message = _parse_message(target_path)

    html_part = _first_part(message, "text/html")
    if html_part is None:
        raise ValueError("Target message does not contain a text/html part.")
    html_intro = _split_html_after_address(html_part.get_content())
    _set_text_part_content(html_part, html_intro + SIGNATURE_HTML_AFTER_ADDRESS, "html")

    text_part = _first_part(message, "text/plain")
    if text_part is not None:
        text_intro = _split_text_after_address(text_part.get_content())
        _set_text_part_content(text_part, text_intro + SIGNATURE_TEXT_AFTER_ADDRESS, "plain")

    target_path.write_bytes(message.as_bytes(policy=policy.SMTP))


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Format .eml files in place by replacing everything after "
            f'"{ADDRESS_MARKER}" with the hardcoded Arch Aerial signature.'
        )
    )
    parser.add_argument("eml_files", nargs="+", help="One or more .eml files to update in place.")
    args = parser.parse_args(argv)

    for raw_path in args.eml_files:
        target_path = Path(raw_path).expanduser().resolve()
        format_eml_in_place(target_path)
        print(f"Updated in place: {target_path}")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main(sys.argv[1:]))
    except Exception as exc:
        print(f"Error: {exc}", file=sys.stderr)
        raise SystemExit(1)
